cd "$(pwd)" && ./venv/bin/python -c '
import os,time,google.cloud.aiplatform as a
from vertexai.resources.preview import feature_store as fs
from google.api_core.exceptions import ResourceExhausted, Conflict
proj=os.environ["GCP_PROJECT"]; loc=os.environ["GCP_LOCATION"]; pfx=os.environ["MLPAB_GCP_PREFIX"]
a.init(project=proj,location=loc,api_transport="rest")
name=f"{pfx}_online_store"
store=None
for i in range(6):
    try:
        existing={s.name for s in fs.FeatureOnlineStore.list()}
        if name in existing:
            store=fs.FeatureOnlineStore(name); print("reusing:",store.name); break
        store=fs.FeatureOnlineStore.create_optimized_store(name)
        print("created:",store.name); break
    except ResourceExhausted as e:
        print(f"attempt {i}: quota exhausted, wait 60s"); time.sleep(60)
    except Conflict as e:
        print(f"attempt {i}: conflict {e}"); time.sleep(30)
if store is None: raise SystemExit("QUOTA: could not create online store")
print("STORE OK:", store.name, store.feature_online_store_type)
'

